with open('scratch/b27_r03_raw_p3.json', 'r', encoding='utf-8') as f:
    raw_data = json.load(f)

assert len(reviewed_data) == 100, f"Expected 100 items, got {len(reviewed_data)}"
for i, item in enumerate(reviewed_data):
    raw_item = raw_data[i]
    assert item['id'] == raw_item['id'], f"ID mismatch at {i}: {item['id']} vs {raw_item['id']}"
    assert item['hw'] == raw_item['hw'], f"HW mismatch at {i}: {item['hw']} vs {raw_item['hw']}"
    assert len(item['vi']) <= 35, f"vi length > 35 for {item['id']} ({item['hw']}): {len(item['vi'])}"
    assert item['status'] == 'reviewed'
    if ' ' not in item['hw']:
        assert item['ipa'].startswith('/') and item['ipa'].endswith('/') and len(item['ipa']) > 2, f"IPA invalid for {item['hw']}"

with open('scratch/b27_r03_p3.json', 'w', encoding='utf-8') as f:
    json.dump(reviewed_data, f, ensure_ascii=False, indent=2)

print(f"Successfully validated and wrote {len(reviewed_data)} items to scratch/b27_r03_p3.json")
